#include <format>
#include <iostream>
#include <limits>
#include <optional>

// a + b, or nothing when the sum doesn't fit in an int. It compares before it adds,
// so the addition only runs when it can't overflow.
[[nodiscard]] constexpr std::optional<int> checked_add(int a, int b) {
  constexpr int max = std::numeric_limits<int>::max();
  constexpr int min = std::numeric_limits<int>::min();
  if (b > 0 && a > max - b) return std::nullopt;
  if (b < 0 && a < min - b) return std::nullopt;
  return a + b;
}

// The compiler runs these calls, and it must reject undefined behaviour while it does.
static_assert(checked_add(std::numeric_limits<int>::max() - 1, 1) == std::numeric_limits<int>::max());
static_assert(!checked_add(std::numeric_limits<int>::max(), 1));
static_assert(!checked_add(std::numeric_limits<int>::min(), -1));

int main() {
  const int speed = std::numeric_limits<int>::max() - 1;
  for (const int step : {1, 2}) {
    if (const auto next = checked_add(speed, step)) {
      std::cout << std::format("{} + {} = {}\n", speed, step, *next);
    } else {
      std::cout << std::format("{} + {} does not fit in an int\n", speed, step);
    }
  }
}

