  explicit Scan(std::ptrdiff_t n) : ranges_(new double[static_cast<std::size_t>(n)]{}) {}
  ~Scan() { delete[] ranges_; }

  [[nodiscard]] double& operator[](std::ptrdiff_t i) { return ranges_[static_cast<std::size_t>(i)]; }
  [[nodiscard]] double operator[](std::ptrdiff_t i) const { return ranges_[static_cast<std::size_t>(i)]; }

 private:
  double* ranges_;
};

