// The mean of the encoder samples, or nothing when there are none.
[[nodiscard]] std::optional<std::int64_t> average(std::span<const int> samples) {
  if (samples.empty()) return std::nullopt;
  const std::int64_t sum = std::accumulate(samples.begin(), samples.end(), 0);
  return sum / std::ssize(samples);
}

int main() {
  const std::vector<int> samples(3, 1'000'000'000);
  if (const auto mean = average(samples)) std::cout << std::format("{}\n", *mean);
}

[[nodiscard]] std::optional<std::int64_t> average(std::span<const int> samples) {
  if (samples.empty()) return std::nullopt;
  std::int64_t sum;
  for (const int s : samples) sum += s;
  return sum / std::ssize(samples);
}

