struct Route {
  std::string name;
  int length_m;
};

// The route with this name, or nullptr when there is none.
[[nodiscard]] const Route* find_route(std::span<const Route> routes, std::string_view name) {
  const auto found = std::ranges::find(routes, name, &Route::name);
  return found == routes.end() ? nullptr : &*found;
}

int main() {
  const std::vector<Route> routes{{.name = "day", .length_m = 120}, {.name = "dock", .length_m = 40}};
  const Route* const night = find_route(routes, "night");
  std::cout << std::format("{} m\n", night->length_m);
}

