#include <iostream>
#include <utility>
#include <vector>

struct Robot {
  int battery_pct = 100;
  int trips = 0;
};

// Calls every handler when a trip ends. It stores the handlers and calls them later.
class TripEvents {
 public:
  void on_trip_end(std::function<void()> handler) { handlers_.push_back(std::move(handler)); }
  void trip_ended() const {
    for (const auto& handler : handlers_) handler();
  }

 private:
  std::vector<std::function<void()>> handlers_;
};

// Start-up wiring: the handler keeps a reference to the counter it increments.
void count_trips(TripEvents& events, int& counter) {
  events.on_trip_end([&counter] { ++counter; });
}

int main() {
  Robot robot;
  TripEvents events;
  count_trips(events, robot.battery_pct);
  for (int trip = 0; trip < 3; ++trip) events.trip_ended();
  std::cout << std::format("battery {}%, trips {}\n", robot.battery_pct, robot.trips);
}

